package com.nextaicommerce.platform.fba;
import static org.junit.jupiter.api.Assertions.*;import java.time.*;import java.math.*;import org.junit.jupiter.api.Test;
class FbaInboundSnapshotTest{
 final Instant at=Instant.parse("2026-11-18T22:34:53.760184Z"),now=at.plusSeconds(3600);
 FbaReadRepository.Stock stock(){return new FbaReadRepository.Stock("SKU",55,777,100,42,999,0,at,BigDecimal.ZERO,null,"USD",null,333);}
 FbaReplenishmentForecasts.InboundSnapshot source(String available,String shipped,String receiving,Instant time,boolean complete,boolean identity,long copies){return new FbaReplenishmentForecasts.InboundSnapshot("SKU",55,100,42,available,shipped,receiving,time,complete,identity,copies,at);}
 @Test void oneSnapshotProducesOne142CommitmentNotWorkingReservedOrTransfer(){var result=FbaReplenishmentForecasts.remainingInbound(stock(),source("55","100","42",at,true,true,1),now);assertNotNull(result);assertEquals(1,result.size());assertEquals(142,result.getFirst().units());assertTrue(result.getFirst().quantityCommitmentVerified());assertFalse(result.getFirst().verified());assertNull(result.getFirst().availableDate());}
 @Test void nullMissingAndMismatchingRequiredFieldsAreUnknownNotZero(){for(var raw:new String[]{null,"","-1","1.5","0","1000"})assertNull(FbaReplenishmentForecasts.remainingInbound(stock(),source("55",raw,"42",at,true,true,1),now));assertNull(FbaReplenishmentForecasts.remainingInbound(stock(),source("55","100",null,at,true,true,1),now));}
 @Test void staleFutureIncrementalOrUnverifiedIdentityNeverCreditsSupply(){assertNull(FbaReplenishmentForecasts.remainingInbound(stock(),source("55","100","42",at,false,true,1),now));assertNull(FbaReplenishmentForecasts.remainingInbound(stock(),source("55","100","42",at,true,false,1),now));assertNull(FbaReplenishmentForecasts.remainingInbound(stock(),source("55","100","42",at,true,true,1),at.plusSeconds(86401)));assertNull(FbaReplenishmentForecasts.remainingInbound(stock(),source("55","100","42",at,true,true,1),at.minusSeconds(1)));}
 @Test void duplicateSnapshotRowsAndWrongSkuAreNotSummed(){assertNull(FbaReplenishmentForecasts.remainingInbound(stock(),source("55","100","42",at,true,true,2),now));var wrong=new FbaReplenishmentForecasts.InboundSnapshot("other",55,100,42,"55","100","42",at,true,true,1,at);assertNull(FbaReplenishmentForecasts.remainingInbound(stock(),wrong,now));}
 @Test void differentSnapshotAsOfAndMissingSourceAreNotReconciledByGuess(){assertNull(FbaReplenishmentForecasts.remainingInbound(stock(),source("55","100","42",at.plusSeconds(1),true,true,1),now));assertNull(FbaReplenishmentForecasts.remainingInbound(stock(),null,now));}
 @Test void originalReportTimestampMustBeFreshEvenIfSnapshotWasRenormalizedNow(){var old=new FbaReplenishmentForecasts.InboundSnapshot("SKU",55,100,42,"55","100","42",at,true,true,1,now.minusSeconds(86401));assertNull(FbaReplenishmentForecasts.remainingInbound(stock(),old,now));var missing=new FbaReplenishmentForecasts.InboundSnapshot("SKU",55,100,42,"55","100","42",at,true,true,1,null);assertNull(FbaReplenishmentForecasts.remainingInbound(stock(),missing,now));}
 @Test void chunks1001SkusWithoutLosingTheLastBatchAndEmptySkipsReads(){var f=org.mockito.Mockito.mock(FbaReplenishmentForecasts.class,org.mockito.Mockito.CALLS_REAL_METHODS);var tenant=java.util.UUID.randomUUID();var store=java.util.UUID.randomUUID();var sizes=new java.util.ArrayList<Integer>();org.mockito.Mockito.doAnswer(i->{java.util.List<String> batch=i.getArgument(2);sizes.add(batch.size());var map=new java.util.HashMap<String,FbaReplenishmentForecasts.InboundSnapshot>();for(var sku:batch)map.put(sku,source("55","100","42",at,true,true,1));return map;}).when(f).inboundSnapshotChunk(org.mockito.ArgumentMatchers.eq(tenant),org.mockito.ArgumentMatchers.eq(store),org.mockito.ArgumentMatchers.anyList());assertTrue(f.inboundSnapshots(tenant,store,java.util.List.of()).isEmpty());assertTrue(sizes.isEmpty());var skus=java.util.stream.IntStream.range(0,1001).mapToObj(n->"S"+n).toList();var result=f.inboundSnapshots(tenant,store,skus);assertEquals(java.util.List.of(200,200,200,200,200,1),sizes);assertEquals(1001,result.size());assertTrue(result.containsKey("S1000"));}
}
